create or replace function public.cf_proef_voor_aanmelden(event jsonb)
returns jsonb
language plpgsql
set search_path = ''
as $hook$
declare
  adres text := lower(coalesce(event->'user'->>'email', ''));
  domein text := split_part(adres, '@', 2);
  aanbieder text := coalesce(event->'user'->'app_metadata'->>'provider', '');
begin
  if adres !~ '^[^@[:space:]]+@[^@[:space:]]+$' then
    return jsonb_build_object('error', jsonb_build_object('http_code', 403, 'message', 'Dit adres heeft geen toegang tot deze app.'));
  end if;
  -- testdatabase: met e-mail (mailcode of wachtwoord) alleen de testaccounts; de vaste
  -- testgebruiker maakt Testdatabase verversen met de admin-API, buiten deze hook om
  if aanbieder = 'email' then
    if adres = any (array['schermtest@klant.nl']::text[]) then
      return '{}'::jsonb;
    end if;
    return jsonb_build_object('error', jsonb_build_object('http_code', 403, 'message', 'Dit adres heeft geen toegang tot deze app.'));
  end if;
  -- via Cloudflare Access: de groepen uit toegang.json, zoals in productie
  if aanbieder <> 'custom:cloudflare' then
    return jsonb_build_object('error', jsonb_build_object('http_code', 403, 'message', 'Dit adres heeft geen toegang tot deze app.'));
  end if;
  -- groep klant
  if (domein = any (array['klant.nl']::text[]) or adres = any (array[]::text[]))
     and not (adres = any (array['jan@klant.nl']::text[])) then
    return '{}'::jsonb;
  end if;
  return jsonb_build_object('error', jsonb_build_object('http_code', 403, 'message', 'Dit adres heeft geen toegang tot deze app.'));
end;
$hook$;

grant execute on function public.cf_proef_voor_aanmelden(jsonb) to supabase_auth_admin;
revoke execute on function public.cf_proef_voor_aanmelden(jsonb) from authenticated, anon, public;

